import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Weekly Review Template","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/weekly-review.en.md","filePath":"public/downloads/worksheets/weekly-review.en.md","lastUpdated":1795488252000}'),n={name:"public/downloads/worksheets/weekly-review.en.md"};function o(l,e,s,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="weekly-review-template" tabindex="-1">Weekly Review Template <a class="header-anchor" href="#weekly-review-template" aria-label="Permalink to &quot;Weekly Review Template&quot;">​</a></h1><p>A review is not a verdict. It gives next week a more accurate starting point. Reserve 20 minutes, inspect evidence before explaining causes, and change one variable only. Do not include passwords, client data, sensitive health information, or unauthorised third-party details.</p><h2 id="weekly-review-—-yyyy-www" tabindex="-1">Weekly Review — YYYY-Www <a class="header-anchor" href="#weekly-review-—-yyyy-www" aria-label="Permalink to &quot;Weekly Review — YYYY-Www&quot;">​</a></h2><h3 id="main-question" tabindex="-1">Main Question <a class="header-anchor" href="#main-question" aria-label="Permalink to &quot;Main Question&quot;">​</a></h3><ul><li>Goal:</li><li>One question this week:</li><li>Acceptance criteria:</li><li>Constraints (time, energy, responsibility):</li></ul><h3 id="evidence-inventory" tabindex="-1">Evidence Inventory <a class="header-anchor" href="#evidence-inventory" aria-label="Permalink to &quot;Evidence Inventory&quot;">​</a></h3><ul><li>Completed:</li><li>Work/recording/test location:</li><li>First, assisted, and delayed-retest locations:</li><li>External reader/user feedback:</li></ul><table tabindex="0"><thead><tr><th>Evidence</th><th>What it shows</th><th>What it does not show yet</th></tr></thead><tbody><tr><td></td><td></td><td></td></tr></tbody></table><h3 id="four-checks-0–2" tabindex="-1">Four Checks (0–2) <a class="header-anchor" href="#four-checks-0–2" aria-label="Permalink to &quot;Four Checks (0–2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Score</th><th>Reason and evidence</th></tr></thead><tbody><tr><td>Completion: was the task done?</td><td style="text-align:right;"></td><td></td></tr><tr><td>Quality: did it meet the standard?</td><td style="text-align:right;"></td><td></td></tr><tr><td>Retention: can it be reproduced days later?</td><td style="text-align:right;"></td><td></td></tr><tr><td>Transfer: does it work under changed conditions?</td><td style="text-align:right;"></td><td></td></tr></tbody></table><h3 id="errors-and-causes" tabindex="-1">Errors and Causes <a class="header-anchor" href="#errors-and-causes" aria-label="Permalink to &quot;Errors and Causes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Error/barrier</th><th>Evidence</th><th>Likely cause</th><th>Next test</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="energy-and-recovery" tabindex="-1">Energy and Recovery <a class="header-anchor" href="#energy-and-recovery" aria-label="Permalink to &quot;Energy and Recovery&quot;">​</a></h3><ul><li>Effect of sleep/stress on performance:</li><li>Unsustainable arrangement:</li><li>What needs pausing or support:</li></ul><h3 id="change-one-variable" tabindex="-1">Change One Variable <a class="header-anchor" href="#change-one-variable" aria-label="Permalink to &quot;Change One Variable&quot;">​</a></h3><ul><li>Keep:</li><li>Stop:</li><li>Adjust:</li><li>Most important task and acceptance criteria:</li><li>Next review date:</li></ul><h3 id="write-back-without-duplicating-records" tabindex="-1">Write Back Without Duplicating Records <a class="header-anchor" href="#write-back-without-duplicating-records" aria-label="Permalink to &quot;Write Back Without Duplicating Records&quot;">​</a></h3><p>Write back only what can change a decision. Do not copy the same paragraph into four files. Choose the file by its job:</p><ul><li><a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a>: compare baseline, immediate performance, delayed retention, and transfer;</li><li><a href="https://byoungd.github.io/up/en/templates/rhythm-ledger" target="_blank" rel="noreferrer">Rhythm Ledger</a>: keep this week&#39;s rhythm, capacity versions, repeated resistance, and next condition to change;</li><li><a href="https://byoungd.github.io/up/en/templates/learning-state" target="_blank" rel="noreferrer">Learning State</a>: keep cross-session handover, unconfirmed facts, boundaries, and the smallest next task;</li><li><a href="https://byoungd.github.io/up/en/templates/90-day-cycle" target="_blank" rel="noreferrer">90-Day Cycle Map</a>: keep phase gates, twelve weekly questions, and the direction of the cycle.</li></ul><p>Evidence Chain updated: yes / no / not applicable<br> Rhythm Ledger updated: yes / no / not applicable<br> Learning State updated: yes / no<br> 90-Day Cycle Map updated: yes / no / not applicable<br> Evidence location for the smallest next task:</p><h2 id="handover-links" tabindex="-1">Handover Links <a class="header-anchor" href="#handover-links" aria-label="Permalink to &quot;Handover Links&quot;">​</a></h2><p>After the review, open only the files whose jobs apply: the <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a> compares four time points; the <a href="https://byoungd.github.io/up/en/templates/rhythm-ledger" target="_blank" rel="noreferrer">Rhythm Ledger</a> records this week&#39;s rhythm; <a href="https://byoungd.github.io/up/en/templates/learning-state" target="_blank" rel="noreferrer">Learning State</a> carries cross-session handover; the <a href="https://byoungd.github.io/up/en/templates/90-day-cycle" target="_blank" rel="noreferrer">90-Day Cycle Map</a> carries cycle gates.</p><p>Do not redesign the whole system after one poor week. Separate random variation from a pattern repeated at least three times; when a pattern persists, change the environment, task size, or support network first.</p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/weekly-review" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-01. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',25)])])}const y=t(n,[["render",o]]);export{u as __pageData,y as default};
